mapper.select:
select id, author_id, book_id, income_date, income_account, income_count, income_number,
       create_time, update_time
from author_income_detail
where author_id = #{authorId}

    and book_id = #{bookId}


    and income_date >= #{startDate}


    and income_date <= #{endDate}

order by income_date desc
